#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node *left;
    struct Node *right;
};

void inorder(struct Node *root) {
    if (root == NULL)
        return;

    printf("%d ", root->data);

    inorder(root->left);
    inorder(root->right);  
}

int main() {
    struct Node *root = malloc(sizeof(struct Node));

    root->data = 1;
    root->left = malloc(sizeof(struct Node));
    root->right = malloc(sizeof(struct Node));

    root->left->data = 2;
    root->left->left = NULL;
    root->left->right = NULL;

    root->right->data = 3;
    root->right->left = NULL;
    root->right->right = NULL;

    inorder(root);

    return 0;
}
